      <el-form-item :label="assessmentMode==='daily'?'待计算SOFA日评估':'变化复核的明确当前日评估'"><el-select :disabled="locked||disabled" v-model="selectedId" aria-label="待计算SOFA日评估" clearable placeholder="明确选择并重新核对完整原来源"><el-option v-for="row in items" :key="row.assessment_id" :value="row.assessment_id" :label="`${row.period_start} 至 ${row.period_end} · ${row.assessment_id}`" :disabled="row.status!=='active'||row.eligible===false" /></el-select></el-form-item>
