      <change-review v-if="assessmentMode==='change'" :patient-id="patientId" :admission-id="admissionId" :current-assessment="selected" :initial-change-assessment-id="initialChangeAssessmentId" :active="active" :locked="locked" :disabled="disabled" @selection="emit('selection',$event)" @availability="emit('availability',$event)" @assessment-created="emit('assessment-created',$event)" />
