        <el-form-item v-for="field in periodFields" :key="field.key" :label="field.label"><el-input v-model="period[field.key]" :aria-label="field.label" placeholder="YYYY-MM-DDTHH:mm:ss.ffffffZ，明确UTC" /></el-form-item>
        <el-button native-type="submit" :loading="preflighting">读取SOFA完整24小时来源清单</el-button>
