          <el-collapse v-if="drugKeys.length"><el-collapse-item v-for="drug in drugKeys" :key="drug" :title="`${drug}：全部物理流关系与剂量基准`" :name="drug"><p>同一命名空间和原流标识保持同一物理流身份，备注不同不会拆成两路。</p><review-fields :model-value="groupReviews[drug]" definition="VasoactiveGroupReview" :prefix="`SOFA${drug}`" @update:model-value="groupReviews[drug]=$event" /></el-collapse-item></el-collapse>
          <section v-for="group in candidate.manifest.conflict_groups" :key="group.group_id" :aria-label="`SOFA冲突裁决 ${group.group_id}`"><p class="hash">完整冲突组 {{ group.group_id }}；成员摘要 {{ group.group_digest }}</p><el-form-item label="SOFA冲突解决状态"><el-select :model-value="conflicts[group.group_id]?.status" aria-label="SOFA冲突解决状态" placeholder="明确选择，不自动选最新或最高" @update:model-value="conflictStatus(group,$event)"><el-option label="未解决，保留不确定" value="unresolved" /><el-option label="已逐条明确裁决" value="resolved" /></el-select></el-form-item><template v-if="conflicts[group.group_id]?.status==='resolved'"><el-form-item v-for="id in group.member_source_ids" :key="id" :label="id"><el-select :model-value="conflictChoices[group.group_id]?.[id]" :aria-label="`SOFA冲突成员 ${id}`" placeholder="每个原成员明确取舍" @update:model-value="chooseConflict(group,id,$event)"><el-option label="接受本原件" value="accepted" /><el-option label="排除此冲突替代原件" value="excluded" /></el-select></el-form-item></template><el-form-item label="SOFA完整冲突裁决依据"><el-input :model-value="conflicts[group.group_id]?.basis_note||''" aria-label="SOFA完整冲突裁决依据" type="textarea" maxlength="1000" @update:model-value="setConflictBasis(group,$event)" /></el-form-item></section>
          <el-form-item label="SOFA日评估备注"><el-input v-model="note" aria-label="SOFA日评估备注" type="textarea" maxlength="1000" /></el-form-item>
          <el-button type="primary" :disabled="!canCreate" :loading="creating" @click="create">仅登记SOFA当前回顾日评估</el-button>
        </template>
      </el-form>
      <el-dialog v-model="editorOpen" title="SOFA原件逐源用途判读" width="min(1050px,96vw)" @closed="!editorOpen&&clearEditor()"><el-form v-if="editingMember" label-position="top"><member-review-editor :member="editingMember" v-model="editorValue" /><p v-if="editorError" role="alert">{{ editorError }}</p></el-form><template #footer><el-button @click="editorOpen=false">取消</el-button><el-button type="primary" :disabled="!editorValid" @click="saveMember">保存本条完整判读</el-button></template></el-dialog>
    </template>
    <p v-else>当前角色不能读取原住院SOFA评估来源。</p>
  </section>
</template>
<script setup>
import { computed, defineAsyncComponent, onActivated, onBeforeUnmount, onDeactivated, ref, watch } from "vue";
import { useStore } from "vuex";
import { createSofaAssessment, getSofaAssessment, getSofaAssessments, getSofaCandidates, revokeSofaAssessment, sofaRevocationMatches, sofaAxes, sofaAxisLabels, sofaClinicalRequestValid, sofaMemberReviewValid, sofaPeriodRequest, verifySofaAssessment, verifySofaManifest, verifySofaProfile } from "@/api/aiSofa";
import { supportCanonical } from "@/api/inpatientSupport";
import ReviewFields from "./ReviewFields.vue";
import MemberReviewEditor from "./MemberReviewEditor.vue";
const props=defineProps({patientId:{type:Number,required:true},admissionId:{type:String,default:""},initialAssessmentId:{type:String,default:""},initialChangeAssessmentId:{type:String,default:""},active:{type:Boolean,default:true},locked:{type:Boolean,default:false},disabled:{type:Boolean,default:false}}),emit=defineEmits(["selection","availability","assessment-created"]);
const ChangeReview=defineAsyncComponent(()=>import("./ChangeReview.vue")),assessmentMode=ref(props.initialChangeAssessmentId?"change":"daily");
const store=useStore(),roles=computed(()=>store.getters["user/permissions"]||[]),allowed=computed(()=>!!store.state.user.accessToken&&roles.value.some(role=>["nurse","doctor","director","admin","super_admin"].includes(role)));
const kinds=["laboratory","map","respiratory_support","arterial_pair","vasoactive","gcs","urine"],kindLabels={laboratory:"受控原检验",map:"原MAP",respiratory_support:"原呼吸支持",arterial_pair:"原血气FiO₂配对",vasoactive:"原连续给入",gcs:"原GCS分项",urine:"原分段尿量"};
const items=ref([]),total=ref(0),listPage=ref(1),selectedId=ref(""),selected=ref(null),loading=ref(false),checking=ref(false),error=ref(""),notice=ref(""),revokeReason=ref(""),revoking=ref(false);
const draftOpen=ref(false),period=ref({period_start:"",period_end:"",as_of:""}),periodFields=[{key:"period_start",label:"SOFA24小时原开始UTC"},{key:"period_end",label:"SOFA24小时原结束UTC"},{key:"as_of",label:"SOFA原资料可用截止UTC"}],candidate=ref(null),preflighting=ref(false),profileId=ref(""),ageMode=ref(""),age=ref(""),ageBasis=ref(""),careSetting=ref(""),careBasis=ref(""),applicability=ref(undefined),note=ref(""),creating=ref(false),draftError=ref("");
const reviews=ref({}),coverage=ref({}),groupReviews=ref({}),conflicts=ref({}),conflictChoices=ref({}),memberPage=ref(1),memberFilter=ref("");
const editorOpen=ref(false),editingMember=ref(null),editorValue=ref({}),editorError=ref("");
let epoch=0,listSequence=0,detailSequence=0,preflightSequence=0,createSequence=0,paused=false,alive=true,initialAllowed=true;
const scope=()=>supportCanonical([props.patientId,props.admissionId,store.state.user.accessToken,roles.value]),capture=()=>({epoch,scope:scope()}),current=ticket=>alive&&!paused&&props.active&&allowed.value&&ticket.epoch===epoch&&ticket.scope===scope();
const profile=computed(()=>candidate.value?.profiles.find(row=>row.rule_profile_id===profileId.value));
const filteredMembers=computed(()=>(candidate.value?.manifest.members||[]).filter(row=>!memberFilter.value||row.kind===memberFilter.value)),visibleMembers=computed(()=>filteredMembers.value.slice((memberPage.value-1)*20,memberPage.value*20));
const drugKeys=computed(()=>[...new Set((candidate.value?.manifest.members||[]).filter(row=>row.kind==="vasoactive").map(row=>row.full_source.reference_snapshots?.drug_mapping?.drug_key))].sort());
const reviewedCount=computed(()=>(candidate.value?.manifest.members||[]).filter(row=>sofaMemberReviewValid(reviews.value[row.member_key],row)).length);
const editorValid=computed(()=>sofaMemberReviewValid(editorValue.value,editingMember.value));
function payload(){const manifest=candidate.value?.manifest;if(!manifest)return null;return{...sofaPeriodRequest(props.patientId,props.admissionId,period.value),rule_profile_id:profileId.value,expected_rule_profile_hash:profile.value?.content_hash,expected_manifest_hash:manifest.content_hash,age_at_period_years:ageMode.value==="unknown"?null:ageMode.value==="known"&&/^(?:0|[1-9]\d*)$/.test(age.value)?Number(age.value):undefined,age_basis_note:ageBasis.value,care_setting:careSetting.value,care_setting_basis_note:careBasis.value,applicability_confirmed:applicability.value,member_reviews:manifest.members.map(row=>reviews.value[row.member_key]),coverage:coverage.value,conflict_reviews:manifest.conflict_groups.map(row=>conflicts.value[row.group_id]),vasoactive_group_reviews:drugKeys.value.map(key=>groupReviews.value[key]),note:note.value};}
const canCreate=computed(()=>{try{return !props.locked&&!props.disabled&&candidate.value?.can_sign===true&&!creating.value&&current(capture())&&!!ageMode.value&&sofaClinicalRequestValid(payload(),candidate.value.manifest,profile.value);}catch{return false;}});
function clearSelection(){detailSequence++;selected.value=null;revokeReason.value="";revoking.value=false;emit("selection",null);emit("availability",false);}
function clearEditor(){editorOpen.value=false;editingMember.value=null;editorValue.value={};editorError.value="";}
function clearReviews(){clearEditor();reviews.value={};coverage.value=Object.fromEntries(sofaAxes.map(axis=>[axis,{}]));groupReviews.value={};conflicts.value={};conflictChoices.value={};ageMode.value=age.value=ageBasis.value=careSetting.value=careBasis.value=note.value="";applicability.value=undefined;draftError.value="";}
function clearPreflight(){preflightSequence++;createSequence++;candidate.value=null;preflighting.value=creating.value=false;profileId.value="";memberPage.value=1;memberFilter.value="";clearReviews();}
function reset(){epoch++;listSequence++;clearSelection();clearPreflight();items.value=[];total.value=0;listPage.value=1;selectedId.value="";draftOpen.value=false;period.value={period_start:"",period_end:"",as_of:""};loading.value=checking.value=false;error.value=notice.value="";}
function refreshDirectory(){if(props.disabled)return;if(props.locked)initialAllowed=true;load();}
async function load(){const ticket=capture(),seq=++listSequence,page=listPage.value;clearSelection();selectedId.value="";items.value=[];error.value="";if(!current(ticket)||!props.admissionId)return;loading.value=true;try{const response=await getSofaAssessments({patient_id:props.patientId,admission_id:props.admissionId,page,page_size:50}),data=response.data;if(!current(ticket)||seq!==listSequence||page!==listPage.value)return;if(!Array.isArray(data?.items)||!Number.isSafeInteger(data.total)||data.items.some(row=>row.patient_id!==props.patientId||row.admission_id!==props.admissionId))throw new Error("SOFA日评估目录与实际原住院不一致");items.value=data.items;total.value=data.total;if(initialAllowed&&props.initialAssessmentId){initialAllowed=false;selectedId.value=props.initialAssessmentId;}}catch(failure){if(current(ticket)&&seq===listSequence)error.value=failure?.message||"当前无法读取原住院SOFA日评估";}finally{if(current(ticket)&&seq===listSequence)loading.value=false;}}
function toggleDraft(){if(props.locked||props.disabled)return;draftOpen.value=!draftOpen.value;clearPreflight();}
async function preflight(){clearPreflight();const ticket=capture(),seq=preflightSequence;if(props.locked||props.disabled||!current(ticket)||!draftOpen.value)return;preflighting.value=true;try{const request=sofaPeriodRequest(props.patientId,props.admissionId,period.value),signature=supportCanonical(period.value),response=await getSofaCandidates(request),data=response.data;if(!current(ticket)||seq!==preflightSequence||signature!==supportCanonical(period.value)||!draftOpen.value)return;if(typeof data?.can_sign!=="boolean"||!Array.isArray(data.profiles)||!await verifySofaManifest(data.manifest,request)||!(await Promise.all(data.profiles.map(verifySofaProfile))).every(Boolean)||data.profiles.some(row=>row.status!=="published"||!row.eligible))throw new Error("SOFA完整清单、固定规则或真实签署资格未符合契约");if(!current(ticket)||seq!==preflightSequence||signature!==supportCanonical(period.value)||!draftOpen.value)return;candidate.value=data;for(const drug of drugKeys.value)groupReviews.value[drug]={drug_key:drug};for(const group of data.manifest.conflict_groups)conflicts.value[group.group_id]={group_id:group.group_id,expected_group_digest:group.group_digest};}catch(failure){if(current(ticket)&&seq===preflightSequence)draftError.value=failure?.message||"SOFA完整原清单预检失败";}finally{if(current(ticket)&&seq===preflightSequence)preflighting.value=false;}}
function editMember(member){clearEditor();editingMember.value=member;editorValue.value=reviews.value[member.member_key]?JSON.parse(supportCanonical(reviews.value[member.member_key])):{kind:member.kind,member_key:member.member_key,expected_content_hash:member.content_hash};editorOpen.value=true;}
function saveMember(){if(!editorValid.value)return;reviews.value[editingMember.value.member_key]=JSON.parse(supportCanonical(editorValue.value));clearEditor();}
function conflictStatus(group,status){conflicts.value[group.group_id]={...conflicts.value[group.group_id],group_id:group.group_id,expected_group_digest:group.group_digest,status,accepted_source_ids:[],excluded_source_ids:[]};conflictChoices.value[group.group_id]={};}
function chooseConflict(group,id,value){const choices=conflictChoices.value[group.group_id]||{};choices[id]=value;conflictChoices.value[group.group_id]=choices;conflicts.value[group.group_id]={...conflicts.value[group.group_id],accepted_source_ids:group.member_source_ids.filter(key=>choices[key]==="accepted"),excluded_source_ids:group.member_source_ids.filter(key=>choices[key]==="excluded")};}
function setConflictBasis(group,value){conflicts.value[group.group_id]={...conflicts.value[group.group_id],group_id:group.group_id,expected_group_digest:group.group_digest,basis_note:value};}
async function create(){if(!canCreate.value)return;const ticket=capture(),seq=++createSequence,values=payload(),signature=supportCanonical(values);clearSelection();selectedId.value="";creating.value=true;draftError.value="";try{const response=await createSofaAssessment(values),row=response.data;if(!current(ticket)||seq!==createSequence||!draftOpen.value||signature!==supportCanonical(payload()))return;if(!await verifySofaAssessment(row,props.patientId,props.admissionId)||row.status!=="active"||row.period_start!==values.period_start||row.period_end!==values.period_end||row.as_of!==values.as_of||supportCanonical(row.snapshot.attestation)!==supportCanonical(values))throw new Error("SOFA登记回执与完整原清单或原住院不一致");if(!current(ticket)||seq!==createSequence||signature!==supportCanonical(payload()))return;draftOpen.value=false;clearPreflight();notice.value="SOFA当前回顾日评估已登记；请明确选择并重核，尚未调用规则模型。";emit("assessment-created",row.assessment_id);await load();}catch(failure){if(current(ticket)&&seq===createSequence){clearPreflight();draftError.value=failure?.message||"SOFA登记失败；完整清单可能变化，请重新预检";clearSelection();}}finally{if(current(ticket)&&seq===createSequence)creating.value=false;}}
async function revoke(){const original=selected.value;if(original?.can_revoke!==true||!revokeReason.value.trim()||revoking.value)return;const ticket=capture(),reason=revokeReason.value.trim();clearSelection();selectedId.value="";revoking.value=true;try{const response=await revokeSofaAssessment(original.assessment_id,{patient_id:props.patientId,admission_id:props.admissionId,expected_revision:original.revision,reason}),row=response.data;if(!current(ticket))return;if(!await sofaRevocationMatches(row,original,props.patientId,props.admissionId))throw new Error("SOFA撤销回执与原版本不一致");if(current(ticket)){notice.value="SOFA原评估已撤销，原件仅保留审计。";await load();}}catch(failure){if(current(ticket))error.value=failure?.message||"SOFA撤销失败，请重新核对当前状态";}finally{if(current(ticket))revoking.value=false;}}
watch(selectedId,async id=>{clearSelection();const ticket=capture(),seq=detailSequence;error.value="";if(!id||!current(ticket))return;checking.value=true;try{const response=await getSofaAssessment(id,{patient_id:props.patientId,admission_id:props.admissionId}),row=response.data;if(!current(ticket)||seq!==detailSequence||id!==selectedId.value)return;if(!await verifySofaAssessment(row,props.patientId,props.admissionId)||row.assessment_id!==id||row.status!=="active"||!row.eligible)throw new Error("SOFA原件、规则或完整成员已变化，不能作为当前计算来源");if(!current(ticket)||seq!==detailSequence||id!==selectedId.value)return;selected.value=row;if(assessmentMode.value==="daily"){emit("selection",{sofa_assessment_id:id});emit("availability",true);}}catch(failure){if(current(ticket)&&seq===detailSequence)error.value=failure?.message||"SOFA原评估无法核对，不能沿用旧资料";}finally{if(current(ticket)&&seq===detailSequence)checking.value=false;}});
watch(assessmentMode,()=>{selectedId.value="";clearSelection();draftOpen.value=false;clearPreflight();});
watch(profileId,(value,previous)=>{if(previous&&value!==previous&&candidate.value){clearReviews();for(const drug of drugKeys.value)groupReviews.value[drug]={drug_key:drug};for(const group of candidate.value.manifest.conflict_groups)conflicts.value[group.group_id]={group_id:group.group_id,expected_group_digest:group.group_digest};}});
watch(()=>supportCanonical(period.value),()=>clearPreflight(),{flush:"sync"});watch(memberFilter,()=>{memberPage.value=1;});
watch([()=>props.patientId,()=>props.admissionId,()=>props.initialAssessmentId,()=>props.initialChangeAssessmentId,()=>props.active,()=>store.state.user.accessToken,()=>supportCanonical(roles.value)],(values,previous)=>{initialAllowed=!previous||values.slice(0,4).some((value,index)=>value!==previous[index]);reset();load();},{immediate:true,flush:"sync"});
onDeactivated(()=>{paused=true;initialAllowed=false;reset();});onActivated(()=>{if(paused){paused=false;reset();load();}});onBeforeUnmount(()=>{alive=false;reset();});
</script>
